import {
  resolveEndpointPath
} from "@ai-matrx/agents/matrx";
const AGENT_START_PATH_TEMPLATE = "/ai/agents/{agent_id}";
const MANDATE_START_PATH_TEMPLATE = "/ai/mandates/{mandate_key}";
function resolveStartPath({
  agentId,
  pinnedVersionId = null,
  mandateKey = null,
  overrideConfig
}) {
  if (!pinnedVersionId && mandateKey) {
    return {
      path: resolveEndpointPath(
        MANDATE_START_PATH_TEMPLATE,
        overrideConfig
      ).replace("{mandate_key}", encodeURIComponent(mandateKey)),
      door: "mandate",
      isVersion: false
    };
  }
  const targetId = pinnedVersionId ?? agentId;
  return {
    path: resolveEndpointPath(AGENT_START_PATH_TEMPLATE, overrideConfig).replace(
      "{agent_id}",
      encodeURIComponent(targetId)
    ),
    door: "agent",
    isVersion: Boolean(pinnedVersionId)
  };
}
export {
  AGENT_START_PATH_TEMPLATE,
  MANDATE_START_PATH_TEMPLATE,
  resolveStartPath
};
