const LAST_REQUEST_CONTEXT_KEY = "last_request_context";
const IDENTITY_KEYS = [
  "organization_id",
  "project_id",
  "task_id",
  "source_app",
  "source_feature",
  "agent_id",
  "agent_version_id",
  "scope_ids"
];
function asNullableString(value) {
  if (typeof value === "string" && value.length > 0) return value;
  return null;
}
function asScopeIds(value) {
  if (!Array.isArray(value)) return [];
  return value.filter((v) => typeof v === "string" && v.length > 0).slice().sort();
}
function snapshotFromPayload(payload, extras) {
  return {
    organization_id: asNullableString(payload.organization_id),
    project_id: asNullableString(payload.project_id),
    task_id: asNullableString(payload.task_id),
    source_app: asNullableString(payload.source_app),
    source_feature: asNullableString(payload.source_feature),
    agent_id: asNullableString(extras?.agent_id),
    agent_version_id: asNullableString(extras?.agent_version_id),
    scope_ids: asScopeIds(payload.scope_ids)
  };
}
function readPreviousRequestContext(metadata) {
  if (!metadata || typeof metadata !== "object") return null;
  const raw = metadata[LAST_REQUEST_CONTEXT_KEY];
  if (!raw || typeof raw !== "object") return null;
  const obj = raw;
  return {
    organization_id: asNullableString(obj.organization_id),
    project_id: asNullableString(obj.project_id),
    task_id: asNullableString(obj.task_id),
    source_app: asNullableString(obj.source_app),
    source_feature: asNullableString(obj.source_feature),
    agent_id: asNullableString(obj.agent_id),
    agent_version_id: asNullableString(obj.agent_version_id),
    scope_ids: asScopeIds(obj.scope_ids)
  };
}
function diffRequestContext(previous, current) {
  const changes = {};
  for (const key of IDENTITY_KEYS) {
    const from = previous[key];
    const to = current[key];
    const same = key === "scope_ids" ? JSON.stringify(from) === JSON.stringify(to) : from === to;
    if (!same) {
      changes[key] = { from, to };
    }
  }
  return changes;
}
function warnRequestContextDrift(args) {
  const { conversationId, isContinuation, previous, current } = args;
  if (!previous) {
    if (isContinuation) {
      console.warn(
        "%c[Matrx CTX] NO previous request context on continuation \u2014 backend may not be recording metadata.last_request_context (or conversation was loaded before that existed).",
        "color: #b45309; font-weight: bold; background: #fef3c7; padding: 2px 6px;",
        { conversationId, current }
      );
    }
    return {};
  }
  const changes = diffRequestContext(previous, current);
  if (Object.keys(changes).length === 0) return {};
  console.warn(
    "%c[Matrx CTX] REQUEST CONTEXT CHANGED vs last turn \u2014 user confirm UX not built yet (FOUND_DEFECTS). Sending anyway.",
    "color: #b45309; font-weight: bold; background: #fef3c7; padding: 2px 6px;",
    { conversationId, changes, previous, current }
  );
  return changes;
}
export {
  LAST_REQUEST_CONTEXT_KEY,
  diffRequestContext,
  readPreviousRequestContext,
  snapshotFromPayload,
  warnRequestContextDrift
};
