import { selectAgentById } from "../redux/agent-definition/selectors.js";
import { getModelRecords, readModelRecords, selectModelById } from "../redux/model-registry.js";
import { setRequestGenerationJob } from "../redux/execution-system/active-requests/active-requests.slice.js";
import { parseCapabilities } from "../model-registry/parse.js";
import { selectCurrentSettings } from "../redux/execution-system/instance-model-overrides/instance-model-overrides.selectors.js";
import { isJobOutputKind, runOutputKindFromModalities } from "../../host/server/run-wait.js";
import { isUuidShape } from "@ai-matrx/kit/uuid";
function selectRunModelId(state, conversationId) {
  const settings = selectCurrentSettings(conversationId)(state);
  const override = settings?.model;
  if (typeof override === "string" && isUuidShape(override)) return override;
  const instance = state.conversations.byConversationId[conversationId];
  const sourceId = instance?.initialAgentVersionId ?? instance?.agentId;
  if (!sourceId) return null;
  return selectAgentById(state, sourceId)?.modelId ?? null;
}
function resolveGenerationJob(state, conversationId) {
  const modelId = selectRunModelId(state, conversationId);
  if (!modelId) return null;
  const model = selectModelById(readModelRecords(), modelId);
  if (!model?.capabilities) return null;
  const kind = runOutputKindFromModalities(
    parseCapabilities(model.capabilities, {
      modelId: model.id,
      modelName: model.name
    }).output
  );
  if (!isJobOutputKind(kind)) return null;
  return {
    kind,
    modelLabel: model.common_name?.trim() || model.name?.trim() || null,
    firstResponseSeconds: null
  };
}
async function labelGenerationJob(dispatch, getState, requestId, conversationId) {
  const modelId = selectRunModelId(getState(), conversationId);
  if (!modelId) return;
  if (!selectModelById(readModelRecords(), modelId)) {
    try {
      await getModelRecords().loadModel(modelId);
    } catch (err) {
      console.warn(
        "[generation-job] could not load the model to label this run; the generic working line stays",
        { modelId, err }
      );
      return;
    }
  }
  const job = resolveGenerationJob(getState(), conversationId);
  if (job) dispatch(setRequestGenerationJob({ requestId, job }));
}
export {
  labelGenerationJob,
  resolveGenerationJob,
  selectRunModelId
};
